#!/usr/bin/env python3
"""Regenerates the Chapter-3 parts of documentation/QUEST_DATABASE.md from the canonical data.

    python3 -P tools/docs/gen_quest_db_c3.py          (Windows: py -3 -P tools/docs/gen_quest_db_c3.py)
    python3 -P tools/docs/gen_quest_db_c3.py --check  (exit 1 if the document is not up to date; writes nothing)

Idempotent: only the text between these marker lines is rewritten (everything else is hand-written):
    <!-- FLOW:BEGIN (generated by tools/docs/gen_quest_db_c3.py) -->  …  <!-- FLOW:END -->   §1 scene-flow table
    <!-- C3:BEGIN (generated by tools/docs/gen_quest_db_c3.py) -->    …  <!-- C3:END -->     §11 Chapter 3
On the first run the FLOW block replaces the §1 table and the C3 block is appended at the end of the file.
Sources (read at run time, so re-run after any text edit): data/v3/*.json (ids, structure, base texts from
locale_de.json), data/chapters/c3.json (expressions, line/option variants, reactions, puzzle UI, cinematic
scenes, level file per scene), data/locale/de_c3_dialogue.json + de_c3p2_dialogue.json (variant and reaction
texts), de_c3_ui.json + de_c3p2_ui.json (puzzle cards, hint, success), de_c3_cinematics.json +
de_c3p2_cinematics.json (inner lines), de_c3_characters.json (people), the level files of the Chapter-3 scenes
(hotspot per objective; several scenes may share one file, C3P2_DESIGN.md §4). Part 2 of the chapter
(documentation/C3P2_DESIGN.md) is generated into the same §11. tests/test_quest_database.gd checks that every id
and German text is present.
"""
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DOC = ROOT / 'documentation' / 'QUEST_DATABASE.md'
GEN = 'tools/docs/gen_quest_db_c3.py'
BLOCKS = {
    'FLOW': ('<!-- FLOW:BEGIN (generated by %s) -->' % GEN, '<!-- FLOW:END -->'),
    'C3': ('<!-- C3:BEGIN (generated by %s) -->' % GEN, '<!-- C3:END -->'),
}
SLICE_SCENES = ['L_A1_Railyard', 'L_M1_Archive']
OPS = {'>=': '≥', '<=': '≤', '==': '=', '!=': '≠', '>': '>', '<': '<'}
# UI text prefix of each Chapter-3 puzzle (cards = <prefix>.card.<symbol>, <prefix>.hint, <prefix>.success)
PUZZLE_UI = {'pz_c3_protocol': 'ui.c3.protocol', 'pz_c3_check': 'ui.c3p2.check'}
CHOICE_PREFIX = 'choice.'     # condition key naming a recorded choice (C3P2_DESIGN §3.2)


def load(rel):
    return json.loads((ROOT / rel).read_text(encoding='utf-8'))


V3 = {stem: load('data/v3/%s.json' % stem) for stem in
      ['flags', 'quests', 'items', 'scenes', 'dialogue', 'puzzles', 'cinematics', 'locale_de']}
CH = load('data/chapters/c3.json')
LOC = dict(V3['locale_de']['strings'])
for f in ['de_c3_dialogue', 'de_c3_ui', 'de_c3_cinematics', 'de_c3_characters', 'de_c3p2_dialogue', 'de_c3p2_ui',
          'de_c3p2_cinematics']:
    LOC.update(load('data/locale/%s.json' % f)['strings'])

SCENES = {s['id']: s for s in V3['scenes']['scenes']}
QUESTS = V3['quests']['quests']
OBJ = {o['id']: (q, o) for q in QUESTS for o in q['objectives']}
ITEMS = {i['id']: i for i in V3['items']['items']}
PUZZLES = {p['id']: p for p in V3['puzzles']['puzzles']}
DIALOGUES = {d['id']: d for d in V3['dialogue']['conversations']}
SEQUENCES = V3['cinematics']['sequences']
FLAGS = V3['flags']['flags']
PROTAGONISTS = V3['flags']['protagonists']
# Chapter 3 only (opening + part 2); Chapter 4 has its own block (tools/docs/gen_quest_db_c4.py, §12)
C3_QUESTS = [q for q in QUESTS if q['scene'] not in SLICE_SCENES and q['title_key'] == 'ui.chapter_c3']
C3_SCENES = [q['scene'] for q in C3_QUESTS]


def t(key):
    if key not in LOC:
        raise SystemExit('missing German text for %s' % key)
    return LOC[key]


def code(x):
    return '`%s`' % x


def ids(xs):
    return ', '.join(code(x) for x in xs) if xs else '—'


def chain():
    out, cur = [], V3['scenes']['start_scene']
    while cur is not None:
        out.append(cur)
        cur = SCENES[cur]['next_scene']
    return out


def when_text(when):
    if not when:
        return 'otherwise'
    parts = []
    for flag, spec in when.items():
        if isinstance(spec, bool):
            parts.append('%s = %s' % (code(flag), 'true' if spec else 'false'))
            continue
        s = str(spec).strip()
        for op in ['>=', '<=', '==', '!=', '>', '<']:
            if s.startswith(op):
                parts.append('%s %s %s' % (code(flag), OPS[op], s[len(op):].strip()))
                break
        else:
            parts.append('%s = %s' % (code(flag), s))
    return ' and '.join(parts)


def effects_text(effects):
    out = []
    for flag, spec in effects.items():
        if 'set' in spec:
            out.append(code('%s = %s' % (flag, 'true' if spec['set'] else 'false')))
        else:
            out.append(code('%s %+d' % (flag, spec['delta'])))
    return ', '.join(out) if out else '—'


def hotspots():
    """objective id -> hotspot id of its interactable in the level file of each Chapter-3 scene"""
    out = {}
    for scene in C3_SCENES:
        res = str(CH.get('levels', {}).get(scene, 'res://scenes/levels/%s.tscn' % scene))
        path = ROOT / res.replace('res://', '')
        if not path.exists():
            continue
        for block in path.read_text(encoding='utf-8').split('\n[node '):
            o = re.search(r'^objective_id = "([^"]+)"', block, re.M)
            h = re.search(r'^hotspot_id = "([^"]+)"', block, re.M)
            if o and h:
                out.setdefault(o.group(1), h.group(1))
    return out


def layers(q):
    """Objectives grouped by prerequisite depth (for the one-line dependency sketch)."""
    depth = {}
    objs = {o['id']: o for o in q['objectives']}

    def d(oid):
        if oid not in depth:
            depth[oid] = 1 + max((d(r) for r in objs[oid].get('requires', [])), default=-1)
        return depth[oid]
    for oid in objs:
        d(oid)
    out = []
    for o in q['objectives']:
        while len(out) <= depth[o['id']]:
            out.append([])
        out[depth[o['id']]].append(o['id'])
    return out


def cinematics_on(trigger_type, trigger_id):
    return [s['id'] for s in SEQUENCES if s.get(trigger_type) == trigger_id]


def _requires_closure(q, oid):
    objs = {o['id']: o for o in q['objectives']}
    seen, todo = set(), list(objs[oid].get('requires', []))
    while todo:
        r = todo.pop()
        if r not in seen:
            seen.add(r)
            todo += objs[r].get('requires', [])
    return seen


def fallback_choice(node_id, q, dialogue_obj):
    """The id of an earlier choice that makes the base line of node_id unreachable in normal play, or None.
    That is the case when every option of a choice completed before the dialogue (any choice of an earlier quest
    of the single chain, or one this objective requires) raises a flag with default 0 that a single-condition
    variant `{flag: ">=1"}` of the node tests: one variant then always matches (first match wins) and the base
    text is only a fallback for level starts without a save (C3_TEXT_REVIEW Befund 23)."""
    tested = set()
    chosen = {}      # objective id -> option ids named by single-condition "choice.<objective>" variants
    for v in CH.get('line_variants', {}).get(node_id, []):
        w = v.get('when') or {}
        if len(w) == 1:
            (flag, spec), = w.items()
            if flag.startswith(CHOICE_PREFIX):
                chosen.setdefault(flag[len(CHOICE_PREFIX):], set()).add(str(spec))
            elif str(spec).replace(' ', '') in ('>=1', '>0'):
                tested.add(flag)
    if not tested and not chosen:
        return None
    before = [o for x in QUESTS[:QUESTS.index(q)] for o in x['objectives']]
    before += [o for o in q['objectives'] if o['id'] in _requires_closure(q, dialogue_obj['id'])]
    for o in before:
        if o['type'] != 'choice' or not o.get('choices'):
            continue
        if o['id'] in chosen and {c['id'] for c in o['choices']} <= chosen[o['id']]:
            return o['id']
        if all(any(f in tested and FLAGS.get(f, {}).get('default') == 0 and spec.get('delta', 0) > 0
                   for f, spec in c.get('effects', {}).items()) for c in o['choices']):
            return o['id']
    return None


def table(head, rows):
    out = ['| ' + ' | '.join(head) + ' |', '|' + '---|' * len(head)]
    out += ['| ' + ' | '.join(r) + ' |' for r in rows]
    return out


# ----------------------------------------------------------------------------------------- FLOW block (§1)
def flow_block():
    rows = []
    for n, sid in enumerate(chain(), 1):
        s = SCENES[sid]
        rows.append([str(n), code(sid), t(s['title_key']), code(s['protagonist']), code(s['camera_mode']),
                     code(s['entry_spawn']), code(s['associated_quest']) if s['associated_quest'] else '—',
                     code(s['exit_on_event']), code(s['next_scene']) if s['next_scene'] else '—',
                     code(s['render_profile'])])
    out = table(['Order', 'Scene', 'Title (de)', 'Protagonist', 'Camera', 'Entry spawn', 'Quest', 'Exit event',
                 'Next scene', 'Render profile'], rows)
    keys = []
    for q in QUESTS:
        k = '%s „%s“' % (code(q['title_key']), t(q['title_key']))
        if k not in keys:
            keys.append(k)
    montage = [s for s in chain() if SCENES[s]['associated_quest'] is None]
    out += ['', 'Start scene: %s. Protagonist switches happen **only** through the completion events (no swap menu).'
            % code(V3['scenes']['start_scene']),
            'Chapter keys for save slots / HUD (quest titles): %s; the montage uses its scene title %s.' % (
                ', '.join(keys), ', '.join(code(SCENES[s]['title_key']) for s in montage)),
            'The finale needs every event of %s: %s.' % (code('slice_end_requires'), ids(V3['quests']['slice_end_requires']))]
    return out


# ----------------------------------------------------------------------------------------- C3 block (§11)
def c3_block():
    hs = hotspots()
    title_key = C3_QUESTS[0]['title_key']
    out = ['## 11. Chapter 3 — „%s“ (Veltrava: the opening and the night of the fire)' % t(title_key), '',
           'Binding design: `documentation/C3_DESIGN.md` (opening: station, palais) and `documentation/C3P2_DESIGN.md` '
           '(part 2: registry, fire, quay). Everything in this section is generated from `data/v3`, '
           '`data/chapters/c3.json` and `data/locale/de_c3*_*.json` by `%s`; edit the data, then re-run the script. '
           'The engine is unchanged: Chapter 3 is seven more quests in the single scene chain, inserted between '
           '`L_M1_Archive` and the montage, so the finale (and the end card) now follows Chapter 3. The four registry '
           'scenes share one level file and hand control over in place (in-level protagonist switch, '
           'TECHNICAL_ARCHITECTURE §12.11). Player-facing variants (line texts, option texts, reactions, cinematic inner '
           'lines) are presentation data read by `scripts/core/chapter_ext.gd`; they never change story state. '
           'Conditions name flags or `choice.<objective>` (the recorded option).' % GEN, '']
    # 11.1 transitions
    out += ['### 11.1 Scene flow and transitions', '']
    rows = []
    for q in [q for q in QUESTS if q['scene'] in ['L_M1_Archive'] + C3_SCENES]:
        s = SCENES[q['scene']]
        nxt = SCENES[s['next_scene']]
        unlocks = [x['id'] for x in QUESTS if q['completion_event'] in x.get('requires_events', [])]
        rows.append([code(q['completion_event']), code(q['objectives'][-1]['id']),
                     ids(cinematics_on('trigger_event', q['completion_event'])),
                     '%s (%s)' % (code(nxt['id']), code(nxt['protagonist'])), ids(unlocks) if unlocks else 'finale gate'])
    out += table(['Event', 'Fired by (last objective)', 'Queues (data order)', 'Scene → (protagonist)', 'Unlocks'], rows)
    out += ['', 'Saves that claim the old demo end (montage / `slice_completed` directly after M1) no longer replay; '
            'every save taken before it stays valid (§9).', '']
    # 11.2 quests
    out += ['### 11.2 Quests', '']
    out += table(['Quest', 'Title (de)', 'Character', 'Scene', 'Gate (`requires_events`)', 'Completion event'],
                 [[code(q['id']), '%s (%s)' % (t(q['title_key']), code(q['title_key'])), code(q['character']),
                   code(q['scene']), ids(q.get('requires_events', [])), code(q['completion_event'])] for q in C3_QUESTS])
    out.append('')
    # 11.3 objectives
    out += ['### 11.3 Objectives', '']
    for n, q in enumerate(C3_QUESTS, 1):
        scene = SCENES[q['scene']]
        out += ['#### 11.3.%d %s — %s (%s)' % (n, code(q['id']), t(scene['title_key']), q['character'].capitalize()), '']
        sketch = ' ─> '.join(' + '.join(lv) for lv in layers(q))
        out += ['```', sketch + ' ══> ' + q['completion_event'], '```', '']
        rows = []
        for o in q['objectives']:
            det = []
            if o['type'] == 'dialogue':
                dlg = DIALOGUES[o['dialogue_id']]
                det.append('%s, %d nodes' % (code(dlg['id']), len(dlg['nodes'])))
                if o.get('grant_item'):
                    det.append('item at the terminal node')
            elif o['type'] == 'puzzle':
                det.append(code(o['puzzle_id']))
                queued = cinematics_on('trigger_objective', o['id'])
                if queued:
                    det.append('queues ' + ids(queued))
            elif o['type'] == 'choice':
                det.append(' / '.join(code(c['id']) for c in o['choices']))
            if o['id'] in hs:
                det.append('hotspot ' + code(hs[o['id']]))
            rows.append([code(o['id']), o['type'], t(o['text_key']), ids(o.get('requires', [])),
                         code(o['grant_item']) if o.get('grant_item') else '—',
                         'per choice (§11.8)' if o['type'] == 'choice' else effects_text(o.get('effects', {})),
                         '; '.join(det)])
        out += table(['Objective', 'Type', 'Objective text (de)', 'Requires', 'Grants', 'Effects', 'Details'], rows)
        out.append('')
    # 11.4 dialogues
    out += ['### 11.4 Dialogues', '',
            'Linear, one node per `advance_dialogue`; resumes at the saved node. *Expr* = portrait expression '
            '(`line_expr`). *Variants* replace the line text when their condition holds (first match wins, '
            '`line_variants`); the base text is the canonical `data/v3` line. Where the variants cover every option '
            'of an earlier mandatory choice, one of them always matches in normal play and the base line is marked '
            '*fallback only* (heard only when a level is started without a save, e.g. `--scene=`); the variants are '
            'then the lines the player actually hears and are written against the following line.', '']
    for q in C3_QUESTS:
        for o in q['objectives']:
            if o['type'] != 'dialogue':
                continue
            dlg = DIALOGUES[o['dialogue_id']]
            extra = '; completing it grants %s' % code(o['grant_item']) if o.get('grant_item') else ''
            out += ['**%s** (objective %s, entry %s%s)' % (code(dlg['id']), code(o['id']), code(dlg['entry_node']), extra), '']
            rows = []
            for node in dlg['nodes']:
                var = ['%s: „%s“ (%s)' % (when_text(v.get('when')), t(v['key']), code(v['key']))
                       for v in CH.get('line_variants', {}).get(node['id'], [])]
                fb = fallback_choice(node['id'], q, o)
                if fb:
                    var.append('*base line = fallback only: every option of %s sets one of these flags*' % code(fb))
                rows.append(['%s%s' % (code(node['id']), ' (end)' if node.get('end') else ''), node['speaker'],
                             CH.get('line_expr', {}).get(node['id'], 'neutral'), code(node['text_key']),
                             t(node['text_key']), '<br>'.join(var) if var else '—'])
            out += table(['Node', 'Speaker', 'Expr', 'Text key', 'Line (de)', 'Variants'], rows)
            out.append('')
    speakers = []
    for q in C3_QUESTS:
        for o in q['objectives']:
            if o['type'] == 'dialogue':
                for node in DIALOGUES[o['dialogue_id']]['nodes']:
                    if node['speaker'] not in PROTAGONISTS and node['speaker'] not in speakers:
                        speakers.append(node['speaker'])
    out += ['Journal „Personen“ (non-protagonist speakers, in the order they are met): ' + ', '.join(
        '%s %s' % (code(s), t('sys.journal.person.%s.name' % s)) for s in speakers) + '.', '']
    # 11.5 puzzle
    out += ['### 11.5 Puzzle', '']
    puzzle_objs = [o for q in C3_QUESTS for o in q['objectives'] if o['type'] == 'puzzle']
    rows = []
    for o in puzzle_objs:
        p = PUZZLES[o['puzzle_id']]
        rows.append([code(p['id']), code(o['id']), code(p['type']), ids(p['clue_item_ids']),
                     ', '.join(p['display_symbols']), code(json.dumps(p['solution'])),
                     '%d failures' % p['hint_after_attempts'], p.get('world_note', '')])
    out += table(['Puzzle', 'Objective', 'Type', 'Clue items (must be owned)', 'Shown', 'Solution', 'Hint after', 'Notes'], rows)
    for o in puzzle_objs:
        p = PUZZLES[o['puzzle_id']]
        pre = PUZZLE_UI.get(p['id'], 'ui.c3.protocol')
        plates = [(sym, LOC.get(pre + '.card.' + sym)) for sym in p['display_symbols']]
        out += ['', '%s cards: ' % code(p['id']) + ', '.join('%s „%s“' % (code(sym), name) for sym, name in plates if name) + '.',
                'Hint (`%s.hint`): „%s“' % (pre, t(pre + '.hint')),
                'Success (`%s.success`): „%s“' % (pre, t(pre + '.success')),
                'UI scene: %s (`open(obj_id)`, signal `solved`).' % code(CH.get('puzzles', {}).get(o['id'], '—'))]
    out += ['Engine semantics as in §4: unlimited retries, no penalty; a list of strings in the wrong order **or of '
            'the wrong length** counts one attempt, a malformed answer (not a list, non-string items) is rejected and '
            'not counted; the UI only submits complete orders (`ui.c3.protocol.incomplete`).', '']
    # 11.6 evidence
    out += ['### 11.6 Evidence', '']
    grant = {o['grant_item']: o['id'] for q in QUESTS for o in q['objectives'] if o.get('grant_item')}
    out += table(['Item', 'Name (de)', 'Description (de)', 'Category', 'Scene', 'Granted by'],
                 [[code(i['id']), t(i['name_key']), t(i['description_key']), i['category'], code(i['scene']),
                   code(grant.get(i['id'], '—'))] for i in V3['items']['items'] if i['scene'] in C3_SCENES])
    out += ['', 'Granted once, in acquisition order, after the six slice items (the canonical route collects them '
            'in the order of this table).', '']
    # 11.7 flags and events
    out += ['### 11.7 Flags and events', '']
    changed = {}     # flag -> [(objective id, label)]
    for q in QUESTS:
        for o in q['objectives']:
            for f in o.get('effects', {}):
                changed.setdefault(f, []).append((o['id'], code(o['id'])))
            for c in o.get('choices', []):
                for f, spec in c.get('effects', {}).items():
                    label = code('%s = %s' % (o['id'], c['id']))
                    changed.setdefault(f, []).append((o['id'], label + (' (%+d)' % spec['delta'] if 'delta' in spec else '')))
    c3_objs = {o['id'] for q in C3_QUESTS for o in q['objectives']}
    rows = []
    for f, meta in FLAGS.items():
        if not any(oid in c3_objs for oid, _ in changed.get(f, [])):
            continue
        rng = '%d–%d' % (meta['min'], meta['max']) if meta['type'] == 'integer' else '—'
        rows.append([code(f), meta['type'], str(meta['default']).lower(), rng, ', '.join(lbl for _, lbl in changed[f])])
    out += table(['Flag', 'Type', 'Default', 'Range', 'Changed by'], rows)
    out += ['', 'Part 2 adds no flag (C3P2_DESIGN §1.1: a v3 save is compared flag by flag on load, so a new flag '
            'would invalidate every existing save); it writes the meters above and the choice history. No combined '
            'morality score.', '']
    reads = {}
    for node, vs in CH.get('line_variants', {}).items():
        for v in vs:
            for f in (v.get('when') or {}):
                reads.setdefault(f, []).append('line ' + code(node))
    for obj, table_ in CH.get('choice_text', {}).items():
        for cid, vs in table_.items():
            for v in vs:
                for f in (v.get('when') or {}):
                    reads.setdefault(f, []).append('option ' + code(cid))
    for obj, table_ in CH.get('reactions', {}).items():
        for cid, vs in table_.items():
            for v in vs:
                for f in (v.get('when') or {}):
                    reads.setdefault(f, []).append('reaction ' + code(cid))
    out += ['Presentation conditions (`data/chapters/c3.json`, first match wins) — this is how the slice callbacks of '
            '§7.3 reach Chapter 3:', '']
    out += table(['Flag read', 'Used by'], [[code(f), ', '.join(dict.fromkeys(reads[f]))] for f in FLAGS if f in reads]
                 + [[code(f), ', '.join(dict.fromkeys(reads[f]))] for f in sorted(reads) if f.startswith(CHOICE_PREFIX)])
    out.append('')
    # 11.8 choices
    out += ['### 11.8 Choices and reactions', '',
            'All options are always offered (the engine does not gate choices by flags); only option texts and '
            'reactions vary. Each decision is applied once, recorded in `choice_history` and the journal, and does '
            'not change progression gating.', '']
    rows = []
    for q in C3_QUESTS:
        for o in q['objectives']:
            if o['type'] != 'choice':
                continue
            for n, c in enumerate(o['choices']):
                var = ['%s: „%s“' % (when_text(v.get('when')), t(v['key']))
                       for v in CH.get('choice_text', {}).get(o['id'], {}).get(c['id'], [])]
                rea = ['%s%s (%s): „%s“ (%s)' % ('' if not v.get('when') else when_text(v['when']) + ' → ', v['speaker'],
                                                 v.get('expr', 'neutral'), t(v['key']), code(v['key']))
                       for v in CH.get('reactions', {}).get(o['id'], {}).get(c['id'], [])]
                rows.append(['%s „%s“' % (code(o['id']), t(o['text_key'])) if n == 0 else '', code(c['id']),
                             t(c['text_key']), effects_text(c.get('effects', {})), '<br>'.join(var) if var else '—',
                             '<br>'.join(rea) if rea else '—'])
    out += table(['Objective', 'Choice id', 'Text (de)', 'Effect', 'Option text variants', 'Reaction'], rows)
    out.append('')
    # 11.9 cinematics
    out += ['### 11.9 Cinematics', '']
    rows = []
    for s in SEQUENCES:
        if s['id'] not in CH.get('cinematics', {}):
            continue
        trig = ('event ' + code(s['trigger_event'])) if s.get('trigger_event') else ('objective ' + code(s['trigger_objective']))
        shots = ', '.join('%s %s (%s s)' % (x['id'], x['shot'], x['duration_s']) for x in s['shots'])
        rows.append([code(s['id']), trig, code(s['skip_policy']), shots, code(CH['cinematics'][s['id']])])
    out += table(['Sequence', 'Trigger', 'Skip policy (data)', 'Shots', 'Scene (§12.5)'], rows)
    out += ['', 'Queued once in data order (`LS_C3_Trains` right after `LS_X1_Final`, both on `m1_completed`; '
            '`LS_C3_Radio` right after `LS_C3_Close`, both on `c3b_completed`); skipping has no story effect. Inner '
            'lines (`data/locale/de_c3_cinematics.json`, `de_c3p2_cinematics.json`, chosen by the scene from '
            '`configure(ctx)` choices and flags):', '']
    out += table(['Key', 'Line (de)'], [[code(k), v] for k, v in LOC.items()
                                       if k.startswith('cin.c3.') or k.startswith('cin.c3p2.')])
    out.append('')
    # 11.10 people
    people = [k[len('char.'):-len('.name')] for k in LOC if k.startswith('char.') and k.endswith('.name')]
    out += ['### 11.10 People of the chapter', '']
    out += table(['Id', 'Name', 'Role', 'Journal note'],
                 [[code(p), t('char.%s.name' % p), t('char.%s.role' % p),
                   LOC.get('sys.journal.person.%s.note' % p, '—')] for p in people])
    out.append('')
    return out


def render(text, name, lines):
    begin, end = BLOCKS[name]
    body = begin + '\n' + '\n'.join(lines).rstrip('\n') + '\n' + end
    if begin in text:
        if text.count(begin) != 1 or text.count(end) != 1 or text.index(end) < text.index(begin):
            raise SystemExit('%s: malformed %s markers' % (DOC, name))
        i, j = text.index(begin), text.index(end) + len(end)
        return text[:i] + body + text[j:]
    if name == 'FLOW':       # first run: the block replaces the §1 table and its "Start scene:" paragraph
        m = re.search(r'^\| Order \| Scene \|.*?\n(?:\|.*\n)+', text, re.M)
        if not m:
            raise SystemExit('%s: §1 scene-flow table not found; add the FLOW markers by hand' % DOC)
        rest = text[m.end():]
        tail = re.match(r'\nStart scene:.*?\n(?=\n)', rest, re.S)
        return text[:m.start()] + body + '\n' + rest[tail.end() if tail else 0:]
    return text.rstrip('\n') + '\n\n---\n\n' + body + '\n'   # first run: C3 block at the end


def main():
    text = DOC.read_text(encoding='utf-8')
    new = render(render(text, 'FLOW', flow_block()), 'C3', c3_block())
    if '--check' in sys.argv:
        if new != text:
            print('%s is out of date — run %s' % (DOC.relative_to(ROOT), GEN))
            sys.exit(1)
        print('up to date')
        return
    if new != text:
        DOC.write_text(new, encoding='utf-8', newline='\n')   # LF on every platform (.gitattributes)
        print('updated %s' % DOC.relative_to(ROOT))
    else:
        print('%s already up to date' % DOC.relative_to(ROOT))


if __name__ == '__main__':
    main()
